  ('r_scone_about_50_scones__6ad', 'Scone (about 50 scones)', 'Pastry', null, 'Production', '', '["Gluten","Milk"]'::jsonb, '["Vegetarian"]'::jsonb, 'https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/0244515dd_IMG_8233.png', '{"final":[],"ingredients":[],"thumbnail":"https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/0244515dd_IMG_8233.png","process":[]}'::jsonb, 10, 'kg', 2440, '[{"text":"Mix flour, baking powder, sugar and margarine. Gradually add milk, and knead until relatively smooth and elastic. Knead in raisins.","use":[{"ingId":"ing_double_cream_jw8","qty":0},{"ingId":"ing_quinoa_xu2","qty":0},{"ingId":"ing_salt_18s","qty":0},{"ingId":"ing_vanilla_4lc","qty":0},{"ingId":"ing_flour_wnk","qty":0},{"ingId":"ing_baking_powder_ab3","qty":0},{"ingId":"ing_margarine_n72","qty":0},{"ingId":"ing_sugar_fyu","qty":0},{"ingId":"ing_raisin_rsy","qty":0}],"image":null,"isTimed":false,"timerSec":0,"estSec":370},{"text":"Roll out to 2 cm high and cut circles 10 cm diameter.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270},{"text":"Bake 145 for 30 min.","use":[],"image":null,"isTimed":true,"timerSec":1800,"estSec":1800}]'::jsonb),
  ('r_baked_cheesecake_classic_sty_2oz', 'Baked Cheesecake - Classic Style', 'Cake', null, 'Production', '', '["Gluten","Eggs","Milk"]'::jsonb, '["Vegetarian"]'::jsonb, null, '{}'::jsonb, 10, 'kg', 9736, '[{"text":"Mix cheese and sugar. Add 12 eggs at a time; mix until smooth.","use":[{"ingId":"ing_full_fat_cheese_luz","qty":4},{"ingId":"ing_granulated_sugar_fv7","qty":800},{"ingId":"ing_eggs_4v8","qty":25}],"image":null,"isTimed":false,"timerSec":0,"estSec":720},{"text":"Meanwhile whip egg whites until firm; add sugar; whip to shiny meringue.","use":[{"ingId":"ing_granulated_sugar_fv7","qty":800},{"ingId":"ing_egg_whites_zys","qty":500}],"image":null,"isTimed":false,"timerSec":0,"estSec":556},{"text":"When all eggs are incorporated, add milk and sifted flour; mix with cheese mixture.","use":[{"ingId":"ing_full_fat_cheese_luz","qty":4},{"ingId":"ing_eggs_4v8","qty":25},{"ingId":"ing_milk_2lb","qty":0.5},{"ingId":"ing_flour_wnk","qty":453.59}],"image":null,"isTimed":false,"timerSec":0,"estSec":720},{"text":"Carefully fold meringue into the cheesy mix.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270},{"text":"Divide between rings lined with digestive biscuit base.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270},{"text":"Bake 1.5-2 hours at 300F. Surface lightly skinned and golden, flexible when pressed. Cool overnight; slice next day with hot knife.","use":[],"image":null,"isTimed":true,"timerSec":7200,"estSec":7200}]'::jsonb),
  ('r_brownie_about_14x20_inches_b_zgs', 'Brownie (about 14x20 inches baking mold)', 'Traybake', null, 'Production', '', '["Eggs","Nuts","Milk"]'::jsonb, '["Vegetarian"]'::jsonb, 'https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/812c5c081_IMG_8209.jpeg', '{"final":[],"ingredients":[],"thumbnail":"https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/812c5c081_IMG_8209.jpeg","process":[]}'::jsonb, 10, 'kg', 2972, '[{"text":"Melt the margarine and chocolate (microwave or low heat). Cool slightly.","use":[{"ingId":"ing_coca_powder_qcf","qty":100},{"ingId":"ing_margarine_n72","qty":950},{"ingId":"ing_dark_chocolate_f0i","qty":900}],"image":null,"isTimed":false,"timerSec":0,"estSec":92},{"text":"Mix eggs with sugar until foamy, light and fluffy.","use":[{"ingId":"ing_eggs_4v8","qty":15},{"ingId":"ing_brown_sugar_ata","qty":750}],"image":null,"isTimed":false,"timerSec":0,"estSec":499},{"text":"Combine chocolate mix with egg mixture; add almond and cocoa; mix until smooth; add walnut pieces.","use":[{"ingId":"ing_dark_chocolate_f0i","qty":900},{"ingId":"ing_ground_almond_xbg","qty":750},{"ingId":"ing_walnut_on_top_q99","qty":0}],"image":null,"isTimed":false,"timerSec":0,"estSec":581},{"text":"Baking: 150, 30 mins. Inside should be still sticky. Cool before slicing.","use":[],"image":null,"isTimed":true,"timerSec":1800,"estSec":1800}]'::jsonb),
