  ('r_viennese_biscuit_gz8', 'Viennese Biscuit', 'Biscuit', 'Pastry', 'Production', '', '["Gluten","Milk"]'::jsonb, '["Vegetarian"]'::jsonb, 'https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/public/68c7f70c8764c9386f5252cb/715c7274a_recipe_page2_img3.png', '{"thumbnail":"https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/public/68c7f70c8764c9386f5252cb/715c7274a_recipe_page2_img3.png","ingredients":["https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/public/68c7f70c8764c9386f5252cb/3e7924444_recipe_page3_img3.png"],"process":[],"final":[]}'::jsonb, 10, 'kg', 1413, '[{"text":"Mix margarine and icing sugar until pale and fluffy, about 5 mins. Add vanilla compound meanwhile.","use":[{"ingId":"ing_margarine_n72","qty":2250},{"ingId":"ing_icing_sugar_xd8","qty":1325},{"ingId":"ing_vanilla_4lc","qty":60}],"image":null,"isTimed":false,"timerSec":0,"estSec":553},{"text":"Slowly add the flour; take care not to overmix.","use":[{"ingId":"ing_flour_wnk","qty":3000}],"image":null,"isTimed":false,"timerSec":0,"estSec":530},{"text":"Immediately put in a piping bag and pipe desired forms.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270},{"text":"Baking: 150, 10-12 mins, until pale and firm, and lightly golden.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":30},{"text":"Fill with jam; dip end with melted dark chocolate.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":30}]'::jsonb),
  ('r_cinnamon_balls_4_big_trays__n7r', 'Cinnamon Balls (4 big trays)', 'Biscuit', 'Pastry', 'Production', '', '["Nuts","Eggs"]'::jsonb, '["Vegetarian","Non-Dairy"]'::jsonb, 'https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/public/68c7f70c8764c9386f5252cb/11292294d_1000174920.jpg', '{"thumbnail":"https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/public/68c7f70c8764c9386f5252cb/11292294d_1000174920.jpg","ingredients":[],"process":[],"final":[]}'::jsonb, 10, 'kg', 1214, '[{"text":"Mix all dry ingredients with the macaron paste on high speed until the lumps disappear.","use":[{"ingId":"ing_ground_almond_xbg","qty":2041},{"ingId":"ing_cinnamon_6cn","qty":100},{"ingId":"ing_macaroon_paste_yp3","qty":1134}],"image":null,"isTimed":false,"timerSec":0,"estSec":304},{"text":"Add golden syrup and egg whites; mix.","use":[{"ingId":"ing_golden_syrup_s39","qty":200},{"ingId":"ing_egg_whites_20__5zf","qty":600}],"image":null,"isTimed":false,"timerSec":0,"estSec":320},{"text":"Form balls, cover with icing sugar, and bake immediately.","use":[{"ingId":"ing_granulated_sugar_fv7","qty":1134}],"image":null,"isTimed":false,"timerSec":0,"estSec":290},{"text":"Baking: 160, 10 mins, until cracks appear on the surface, but still soft inside.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":30},{"text":"The raw mix can be stored in refrigerator for a week.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270}]'::jsonb),
