  ('r_marble_cake_vqu', 'Marble Cake', 'Cake', null, 'Production', '', '["Gluten","Eggs"]'::jsonb, '["Vegetarian","Non-Dairy"]'::jsonb, 'https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/cb0168457_edited-image.jpg', '{"final":[],"ingredients":[],"thumbnail":"https://base44.app/api/apps/68c7f70c8764c9386f5252cb/files/mp/public/68c7f70c8764c9386f5252cb/cb0168457_edited-image.jpg","process":[]}'::jsonb, 10, 'kg', 2840, '[{"text":"Mix oil, eggs and sugar until light and creamy; add vanilla compound.","use":[{"ingId":"ing_oil_pd5","qty":0},{"ingId":"ing_eggs_4v8","qty":0},{"ingId":"ing_sugar_fyu","qty":0},{"ingId":"ing_vanilla_compound_vo8","qty":0}],"image":null,"isTimed":false,"timerSec":0,"estSec":350},{"text":"Sift flours and baking powder together; add flour and orange juice, stirring constantly.","use":[{"ingId":"ing_flour_wnk","qty":0},{"ingId":"ing_baking_powder_ab3","qty":0},{"ingId":"ing_orange_juice_8c5","qty":0},{"ingId":"ing_coca_powder_qcf","qty":0}],"image":null,"isTimed":false,"timerSec":0,"estSec":110},{"text":"Divide the dough in half; add cocoa powder + some water to one part.","use":[{"ingId":"ing_baking_powder_ab3","qty":0},{"ingId":"ing_coca_powder_qcf","qty":0}],"image":null,"isTimed":false,"timerSec":0,"estSec":310},{"text":"Layer in the paper cups (or mix with chocolate chips for muffins).","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":270},{"text":"Bake at 150 until ~30 mins or until skewer comes out clean.","use":[],"image":null,"isTimed":true,"timerSec":1800,"estSec":1800}]'::jsonb),
  ('r_almond_crescent_half_moon_bi_m6u', 'Almond Crescent (Half-Moon Biscuit)', 'Biscuit', null, 'Production', '', '["Gluten","Eggs","Nuts","Milk"]'::jsonb, '["Vegetarian"]'::jsonb, null, '{}'::jsonb, 10, 'kg', 1366, '[{"text":"Mix margarine with sugar, flour and ground almond until crumbly, then add egg yolks and mix until combined.","use":[{"ingId":"ing_margarine_n72","qty":1000},{"ingId":"ing_sugar_preferably_icing_s_qr9","qty":500},{"ingId":"ing_ground_almond_xbg","qty":700},{"ingId":"ing_egg_yolks_lss","qty":7},{"ingId":"ing_flour_wnk","qty":1200},{"ingId":"ing_almond_flavour_fez","qty":2}],"image":null,"isTimed":false,"timerSec":0,"estSec":720},{"text":"On lightly floured surface roll it into long stripes around 2 cm in diameter. Cut up into 2-3 cm long pieces, and shape into small crescents/half moons.","use":[{"ingId":"ing_flour_wnk","qty":1200}],"image":null,"isTimed":false,"timerSec":0,"estSec":530},{"text":"Leave space between them as they will flatten a bit.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":30},{"text":"Baking: 150, 10 mins, until pale and firm.","use":[],"image":null,"isTimed":false,"timerSec":0,"estSec":30},{"text":"Dust with icing sugar, or dip into melted chocolate.","use":[{"ingId":"ing_sugar_preferably_icing_s_qr9","qty":500}],"image":null,"isTimed":false,"timerSec":0,"estSec":56}]'::jsonb),
